mapper.select:
select from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id left join biz_case ca on ca.contract_id=c.contract_id and ca.del_flag='0' left join sys_user u on u.user_id=c.owner_id
and c.del_flag='0' and (c.contract_no like concat('%',#{keyword},'%') or ca.case_no like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%')) and c.contract_no like concat('%',#{contractNo},'%') and ca.case_no like concat('%',#{caseNo},'%') and c.customer_name like concat('%',#{customerName},'%') and p.confirm_status=#{confirmStatus} and p.invoice_status=#{invoiceStatus} and c.owner_id=#{ownerId} and c.risk_level=#{riskLevel}
and (p.plan_receive_date is null or datediff(curdate(), p.plan_receive_date) <= 0) and datediff(curdate(), p.plan_receive_date) between 1 and 30 and datediff(curdate(), p.plan_receive_date) between 31 and 60 and datediff(curdate(), p.plan_receive_date) between 61 and 90 and datediff(curdate(), p.plan_receive_date) > 90
order by p.plan_receive_date asc, p.plan_id desc limit #{dashboardLimit}

select , concat('HK', date_format(ifnull(p.update_time, p.create_time), '%Y%m%d'), lpad(p.plan_id, 4, '0')) paymentNo, p.update_time paymentDate, p.finance_user_id financeUserId from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id left join biz_case ca on ca.contract_id=c.contract_id and ca.del_flag='0' left join sys_user u on u.user_id=c.owner_id
and c.del_flag='0' and (c.contract_no like concat('%',#{keyword},'%') or ca.case_no like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%')) and p.confirm_status=#{confirmStatus} and c.owner_id=#{ownerId}
order by case when p.confirm_status='0' then 0 else 1 end, p.update_time desc, p.plan_id desc limit #{dashboardLimit}

select , concat('KP', date_format(ifnull(p.update_time, p.create_time), '%Y%m%d'), lpad(p.plan_id, 4, '0')) invoiceApplyNo, case when p.invoice_status='1' then concat('FP', date_format(p.update_time, '%Y%m%d'), lpad(p.plan_id, 4, '0')) else null end invoiceNo from biz_contract_fee_plan p left join biz_contract c on c.contract_id=p.contract_id left join biz_case ca on ca.contract_id=c.contract_id and ca.del_flag='0' left join sys_user u on u.user_id=c.owner_id
and c.del_flag='0' and (c.contract_no like concat('%',#{keyword},'%') or ca.case_no like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%')) and p.confirm_status=#{confirmStatus} and p.invoice_status=#{invoiceStatus}
order by p.update_time desc, p.plan_id desc

select e.*, c.case_no caseNo, c.case_name caseName, c.customer_name customerName, c.contract_no contractNo,
       c.case_type caseType, c.case_status caseStatus, c.main_lawyer_name mainLawyerName,
       ct.contract_name contractName, ct.sign_amount contractSignAmount
from biz_case_expense e
left join biz_case c on c.case_id=e.case_id
left join biz_contract ct on ct.contract_id=c.contract_id and ct.del_flag='0'

    and e.del_flag='0' and c.del_flag='0'
    and (e.expense_no like concat('%',#{keyword},'%') or c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%'))
    and e.case_id=#{caseId}
    and e.expense_type=#{expenseType}
    and e.pay_status=#{payStatus}
    and e.reimburse_status=#{reimburseStatus}
    and e.voucher_status=#{voucherStatus}


order by e.occur_date desc, e.expense_id desc
